(function(){'use strict';var suppress=false;var relay=['hq:employee-move','hq:employee-arrived','hq:assign-task','hq:screen-selected','hq:employee-selected','hq:room-selected','hq:task-selected','hq:project-selected','hq:run-task','hq:open-task','hq:open-project','hq:employee-meeting','hq:nawaf-office-selected','hq:workstation-interaction'];relay.forEach(function(name){window.addEventListener(name,function(e){if(suppress&&name==='hq:assign-task')return;parent.postMessage({source:'nawaf-hq-office',type:name,detail:e.detail||{}},'*')})});function clickMode(mode){var b=document.querySelector('[data-mode="'+mode+'"]');if(b)b.click()}function indexOfEmployee(id){try{var s=JSON.parse(localStorage.getItem('nawaf-hq-v5')||'{}');var i=(s.employees||[]).findIndex(function(e){return e.id===id});return i<0?0:i}catch(e){return 0}}function routeEmployee(id,status){if(!window.NawafOfficeV15||!window.NawafOfficeV15.moveEmployee||!window.THREE)return;var i=indexOfEmployee(id),slots=[[-13,-5],[-6.7,-5],[6.7,-5],[13,-5],[-13,5],[-6.7,5],[6.7,5],[13,5]],s=slots[i]||slots[0],to,mode=status||'READY';if(status==='WAITING_FOR_NAWAF'){to=new THREE.Vector3(-3.1+(i%4)*2.05,.12,-8.5+Math.floor(i/4)*1.3);mode='MEETING'}else if(status==='REVIEWING'){to=new THREE.Vector3(-2.5+(i%4)*1.7,.12,.8+Math.floor(i/4)*1.1);mode='REVIEW'}else{to=new THREE.Vector3(s[0]-.15,.12,s[1]-.82);mode=status==='WORKING'||status==='RESEARCHING'?status:'READY'}window.NawafOfficeV15.moveEmployee(id,to,mode)}window.addEventListener('message',function(e){var m=e.data||{};if(m.source!=='nawaf-hq-dashboard')return;if(m.action==='mode')clickMode(m.mode);if(m.action==='assignTask'&&window.NawafOfficeV15&&window.NawafOfficeV15.assignTask){suppress=true;window.NawafOfficeV15.assignTask(m.employeeId,m.taskType);suppress=false}if(m.action==='routeEmployee')routeEmployee(m.employeeId,m.status);if(m.action==='meeting'&&window.NawafOfficeV15&&window.NawafOfficeV15.meeting)window.NawafOfficeV15.meeting();if(m.action==='review'&&window.NawafOfficeV15&&window.NawafOfficeV15.review)window.NawafOfficeV15.review();if(m.action==='collab'&&window.NawafOfficeV15&&window.NawafOfficeV15.collab)window.NawafOfficeV15.collab();if(m.action==='work'&&window.NawafOfficeV15&&window.NawafOfficeV15.work)window.NawafOfficeV15.work()});setTimeout(function(){parent.postMessage({source:'nawaf-hq-office',type:'hq:office-ready',detail:{version:'18'}},'*')},350)})();